// lookup demo — Granite (jahdb demo program)
var DATA={"Granite":"Granite is the classic intrusive igneous rock, cooling slowly underground so its quartz, feldspar, and mica grow into visible interlocking crystals. It forms the cores of continents and polishes into the countertops and monuments of everyday life."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("igneous, intrusive"));

